#!/bin/bash
# ============================================================
# Telegram Guard accuracy patch — auto-apply script
#
# What this does:
#   1. Backs up the 3 files it touches into ./telegram_guard_patch_backup_<timestamp>/
#   2. Overwrites them with the corrected versions
#
# Files touched:
#   - android/app/src/main/assets/adult_keywords.txt
#       Rewritten: was full of porn-site BRAND NAMES (pornhub, xhamster, jasmin,
#       beeg, tiava, shameless, homo, tranny...) being used as generic keyword
#       matches against ordinary chat/search text. That caused false positives
#       (innocent names/words like "Jasmin", "shameless" getting blocked) and
#       false negatives (real explicit sentences without a site name in them
#       sailing through). Now contains only genuine generic content words.
#
#   - android/app/src/main/java/.../shield/core/TelegramGuard.java
#       Join-sheet detection now scans the group/channel's own name and
#       description text directly for keyword hits, instead of only firing
#       when the screen was already flagged in the last 90 seconds. This
#       blocks adult-named groups on the FIRST join sheet seen, before you
#       ever enter the chat.
#
#   - android/app/src/main/java/.../shield/ShieldAccessibilityService.java
#       a) ADULT_DOMAIN_PATTERNS expanded with all the site-brand names that
#          were removed from adult_keywords.txt, so URL/domain-based blocking
#          coverage is preserved (those names still block on the web/URL side,
#          just no longer misfire on free chat text).
#       b) CONTENT_SCAN_PACKAGES and IN_APP_WEBVIEW_PACKAGES now include the
#          Telegram forks (Nekogram, Telegram X, Plus Messenger, etc.) that
#          TelegramGuard.isTelegram() already recognized, so typed-keyword
#          blocking and webview URL scanning work on forks too, not just the
#          official Telegram app.
#
# Run this from your project ROOT folder:
#   bash apply_telegram_guard_patch.sh
# ============================================================

set -e

if [ ! -d "android/app/src/main/java/com/mylifeos/app/shield" ]; then
  echo "ERROR: run this script from the project ROOT folder (android/ not found here)."
  exit 1
fi

STAMP=$(date +%Y%m%d_%H%M%S)
BACKUP_DIR="telegram_guard_patch_backup_$STAMP"
mkdir -p "$BACKUP_DIR"

backup_and_write() {
  local target="$1"
  local content_file="$2"
  mkdir -p "$(dirname "$target")"
  if [ -f "$target" ]; then
    mkdir -p "$BACKUP_DIR/$(dirname "$target")"
    cp "$target" "$BACKUP_DIR/$target"
  fi
  cp "$content_file" "$target"
  echo "  updated: $target"
}

WORKDIR=$(mktemp -d)
trap 'rm -rf "$WORKDIR"' EXIT

echo "Backing up + applying patch..."
echo "Backups going to: $BACKUP_DIR/"
echo ""
FILE_1_B64="cG9ybgpzZXgKeHh4CmhlbnRhaQpudWRlcwplcm90aWMKbnNmdwpjYW1naXJscwpvbmx5ZmFucwo="
echo "${FILE_1_B64}" | base64 -d > "$WORKDIR/decoded_1"
backup_and_write "android/app/src/main/assets/adult_keywords.txt" "$WORKDIR/decoded_1"

FILE_2_B64=""
echo "${FILE_2_B64}" | base64 -d > "$WORKDIR/decoded_2"
backup_and_write "android/app/src/main/java/com/mylifeos/app/shield/core/TelegramGuard.java" "$WORKDIR/decoded_2"

FILE_3_B64=""
echo "${FILE_3_B64}" | base64 -d > "$WORKDIR/decoded_3"
backup_and_write "android/app/src/main/java/com/mylifeos/app/shield/ShieldAccessibilityService.java" "$WORKDIR/decoded_3"

echo ""
echo "Done. 3 files updated, backups saved in $BACKUP_DIR/"
echo ""
echo "Next steps:"
echo "  1. If you use scripts/sync-shield-lists.mjs, run it now so"
echo "     public/shield/adult_keywords.txt mirrors the updated asset file:"
echo "       node scripts/sync-shield-lists.mjs"
echo "  2. Rebuild the APK as usual."
